(function(){
function msHexToRgb(h){h=h.replace("#","");return parseInt(h.substring(0,2),16)+","+parseInt(h.substring(2,4),16)+","+parseInt(h.substring(4,6),16);}
document.addEventListener("DOMContentLoaded",function(){
var p=document.querySelector(".post-body,.entry-content");if(!p)return;
var bc=getComputedStyle(document.documentElement).getPropertyValue("--blogcolor").trim()||"#cc0000";
var rgb=msHexToRgb(bc);
document.documentElement.style.setProperty("--ms-primary",bc);
document.documentElement.style.setProperty("--ms-bg","rgba("+rgb+",0.04)");
document.documentElement.style.setProperty("--ms-border","rgba("+rgb+",0.25)");
var r=null;
var f=p.querySelector('ul li[id^="ref1"]');if(f)r=f.closest("ul");
if(!r){var t=p.querySelector('table tr[id^="ref1"]');if(t)r=t.closest("table");}
if(!r)return;r.classList.add("masaha-source-box");
var refs=Array.from(r.querySelectorAll('li[id^="ref"],tr[id^="ref"]'));if(!refs.length)return;
refs.forEach(function(e,i){var n=i+1;addNum(e,n);updateCite(p,n);});
});
function addNum(ref,number){
var el=ref.tagName==="TR"?ref.querySelector("td:first-child"):ref;if(!el)return;
if(el.querySelector(".ms-number-wrapper"))return;
var w=document.createElement("span");w.className="ms-number-wrapper";
w.innerHTML="<span class='ms-brack'>[</span><span class='ms-num'>"+number+"</span><span class='ms-brack'>]</span>&nbsp;";
var replaced=false;
for(var i=0;i<el.childNodes.length;i++){
var node=el.childNodes[i];var txt="";
if(node.nodeType===3)txt=node.textContent;
else if(node.nodeType===1&&(node.tagName==="B"||node.tagName==="SPAN"||node.tagName==="A"))txt=node.textContent;
else continue;
var patterns=[/^\[(\d+)\]/,/^(\d+)\./,/^\((\d+)\)/];
for(var j=0;j<patterns.length;j++){
var m=txt.match(patterns[j]);if(m&&parseInt(m[1])===number){
var rest=document.createTextNode(txt.substring(m[0].length));
el.replaceChild(w,node);el.insertBefore(rest,w.nextSibling);
replaced=true;break;}
}if(replaced)break;}
if(!replaced)el.insertBefore(w,el.firstChild);
var a=el.querySelector("a[href^='http']");if(a){
if(!a.dataset.originalText)a.dataset.originalText=(a.textContent||"").trim();
a.textContent=a.dataset.originalText;a.setAttribute("title",a.href);
a.setAttribute("target","_blank");a.setAttribute("rel","noopener noreferrer");}
}
function updateCite(postBody,number){
var c=postBody.querySelector("#cite"+number);
if(c){if(c.textContent.trim()==="["+number+"]"){c.classList.add("masaha-cite-number");return;}
c.textContent="["+number+"]";c.classList.add("masaha-cite-number");}
}
})();
//

