document.addEventListener('DOMContentLoaded', function() {
    var vault = document.getElementById('seoturbo-discover-vault');
    if (!vault) return;
    var siteTypeMeta = document.querySelector('meta[name="site-type"]');
    var rawSiteType = (siteTypeMeta && siteTypeMeta.content.trim() !== "") ? siteTypeMeta.content.trim() : "Organization";
    var publisherType = (rawSiteType === "NewsMediaOrganization") ? "NewsMediaOrganization" : "Organization";
    var isRecipe = document.querySelector('.cooking-table') !== null;
    var articleType = 'BlogPosting'; 
    if (isRecipe) {
        articleType = 'Recipe';
    } else if (rawSiteType === 'TechnologyOrganization') {
        articleType = 'TechArticle';
    } else if (rawSiteType === 'NewsMediaOrganization') {
        articleType = 'NewsArticle';
    }
    if (articleType !== 'Recipe') {
        var discoverSchema = {
            "@context": "https://schema.org",
            "@type": articleType,
            "mainEntityOfPage": {
              "@type": "WebPage",
              "@id": vault.getAttribute('data-url')
            },
            "headline": vault.getAttribute('data-headline'),
            "image": [
              vault.getAttribute('data-img1'),
              vault.getAttribute('data-img2'),
              vault.getAttribute('data-img3')
            ],
            "datePublished": vault.getAttribute('data-pub'),
            "dateModified": vault.getAttribute('data-mod'),
            "author": {
              "@type": "Person",
              "name": vault.getAttribute('data-author'),
              "url": vault.getAttribute('data-authorurl')
            },
            "publisher": {
              "@type": publisherType,
              "name": vault.getAttribute('data-blogname'),
              "logo": {
                "@type": "ImageObject",
                "url": vault.getAttribute('data-logo'),
                "width": 192,
                "height": 192
              }
            }
        };
        var ldJsonScript = document.createElement('script');
        ldJsonScript.type = 'application/ld+json';
        ldJsonScript.text = JSON.stringify(discoverSchema);
        document.head.appendChild(ldJsonScript);
    }
});
