div.script:
//
document.addEventListener("DOMContentLoaded", function() {
    var adWrappers = document.querySelectorAll('.ad-wrapper-footer-col');
    adWrappers.forEach(function(wrapper) {
        var contentEl = wrapper.querySelector('.widget-content');
        var hasContent = false;
        if (contentEl) {
            if (contentEl.innerHTML.trim() !== "") {
                hasContent = true;
            }
        }
        var hasAds = false;
        var adElements = wrapper.querySelectorAll('ins, iframe, img, a');
        if (adElements.length > 0) {
            hasAds = true;
        }
        if (!hasContent) {
            if (!hasAds) {
                wrapper.style.display = 'none';
                var parentCol = wrapper.closest('.footer-col');
                if (parentCol) {
                    var colText = parentCol.textContent.trim();
                    var colAds = parentCol.querySelectorAll('img, iframe, ins');
                    if (colText === "") {
                        if (colAds.length === 0) {
                            parentCol.style.display = 'none';
                        }
                    }
                }
            }
        }
    });
    /* إخفاء حاويات الفوتر الفارغة */
    var emptyContainers = [
        '.footer-top-content-container',
        '.footer-top-ad-container',
        '.footer-bottom-content-container',
        '.footer-bottom-ad-container',
        '.ad-wrapper-home-footer'
    ];
    emptyContainers.forEach(function(sel) {
        var el = document.querySelector(sel);
        if (el) {
            var visibleWidget = el.querySelector('.widget:not([style*="display: none"])');
            if (!visibleWidget) {
                el.style.display = 'none';
            }
        }
    });
});
