b:if.script:
//
(function() {
    'use strict';
    ['contextmenu', 'copy', 'cut', 'paste', 'dragstart', 'drop', 'selectstart'].forEach(ev => {
        document.addEventListener(ev, e => {
            if (e.target.closest('input, textarea, #comment-editor, .action-btn, .share-button')) return;
            e.preventDefault(); e.stopPropagation();
        }, true);
    });
    document.addEventListener('keydown', function(e) {
        const k = e.key.toLowerCase(), c = e.ctrlKey || e.metaKey, s = e.shiftKey;
        if (c && ['c', 'v', 'x', 'a', 's', 'u', 'p'].includes(k)) {
            e.preventDefault(); e.stopPropagation();
            if(k === 'u') alert('🔒 عرض مصدر الصفحة معطل');
            return false;
        }
        if (e.key === 'F12' || (c && s && ['i', 'j', 'c'].includes(k))) {
            e.preventDefault(); return false;
        }
    }, true);
    document.addEventListener('copy', e => {
        if (e.target.closest('.action-btn')) return;
        e.clipboardData.setData('text/plain', '⚠️ محتوى محمي © يمنع النسخ من موقعنا');
        e.preventDefault();
    });
    window.addEventListener('beforeprint', e => { e.preventDefault(); alert('❌ الطباعة معطلة'); });
})();
